let category='all';
const mode=document.querySelector('#mode');
const list=document.querySelector('#programme-list');
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function element(tag,className,text){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;}
function icon(kind='arrow'){
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.classList.add(kind);const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',kind==='plus'?'M5 12h14M12 5v14':'M5 12h14m-6-6 6 6-6 6');svg.append(path);return svg;
}
function renderProgrammes(animate=false){
 const openIds=new Set([...list.querySelectorAll('details[open]')].map(node=>node.dataset.programme));
 const matches=programmes.filter(programme=>(category==='all'||programme.category===category)&&(mode.value==='all'||programme.mode===mode.value));
 list.replaceChildren();
 for(const programme of matches){
  const copy=programme[locale],labels=words[locale];
  const details=element('details','programme');details.dataset.programme=programme.id;details.open=openIds.has(programme.id);
  const summary=element('summary');const heading=element('div');heading.append(element('h3','',copy.name),element('span','programme-category',t(programme.category)));
  const meta=element('div','programme-meta');meta.append(element('strong','',copy.duration),element('span','',copy.pace));
  summary.append(heading,meta,element('span','programme-mode',t(programme.mode)),icon('plus'));
  const detail=element('div','programme-detail');const intro=element('div');intro.append(element('h4','',labels.audience),element('p','',copy.audience));
  const link=element('a','button secondary',labels.advice);link.href='#consultation';link.setAttribute('aria-label',labels.advice+': '+copy.name);link.append(icon());
  link.addEventListener('click',()=>{document.querySelector('#interest').value=programme.id;});
  intro.append(link,element('p','detail-note',labels.example));
  const modules=element('div','detail-modules');modules.append(element('h4','',labels.modules));const ul=element('ul');copy.modules.forEach(text=>ul.append(element('li','',text)));modules.append(ul);
  detail.append(intro,modules);details.append(summary,detail);list.append(details);
 }
 document.querySelector('#result-count').textContent=matches.length+' '+(matches.length===1?words[locale].countOne:words[locale].countMany);
 document.querySelector('#empty').hidden=matches.length>0;
 document.querySelectorAll('[data-filter]').forEach(button=>{const active=button.dataset.filter===category;button.setAttribute('aria-pressed',String(active));button.classList.toggle('selected',active);});
 if(animate&&!reduceMotion()&&list.animate)list.animate([{opacity:.7,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:230,easing:'cubic-bezier(.16,1,.3,1)'});
}
function renderFunding(){const copy=fundingAdvice[document.querySelector('#situation').value][locale];document.querySelector('#funding-response').replaceChildren(element('h3','',copy[0]),element('p','',copy[1]));}
function renderPreview(){
 const labels=words[locale];
 document.querySelector('#preview').textContent=labels.interest+': '+document.querySelector('#interest').selectedOptions[0].textContent+'\n'+labels.consultation+': '+document.querySelector('#contact-mode').selectedOptions[0].textContent+'\n\n'+(document.querySelector('#message').value.trim()||labels.defaultMessage);
}
function applyLocale(){
 document.documentElement.lang=locale;
 document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=t(node.dataset.i18n));
 document.title=locale==='en'?'Weiterwerk · Your next step starts here.':'Weiterwerk · Dein nächster Schritt beginnt hier.';
 document.querySelector('meta[name="description"]').content=locale==='en'?'Fictional adult education and training centre design demo. Explore retraining, skills courses, coaching and a local consultation preview.':'Fiktives Bildungszentrum als interaktive Design-Demo: Umschulung, Weiterbildung, Coaching und lokale Beratungsvorschau.';
 const toggle=document.querySelector('#locale');toggle.setAttribute('aria-label',locale==='en'?'Auf Deutsch wechseln':'Switch to English');toggle.setAttribute('aria-pressed',String(locale==='en'));toggle.querySelectorAll('[lang]').forEach(node=>node.classList.toggle('active',node.lang===locale));
 document.querySelector('#menu').setAttribute('aria-label',locale==='en'?'Navigation menu':'Navigationsmenü');
 document.querySelector('#navigation').setAttribute('aria-label',locale==='en'?'Main navigation':'Hauptnavigation');
 document.querySelector('.filters').setAttribute('aria-label',locale==='en'?'Programme category':'Bildungsbereich');
 document.querySelector('.brand').setAttribute('aria-label',locale==='en'?'Weiterwerk home':'Weiterwerk Startseite');
 document.querySelector('.hero-visual img').alt=locale==='en'?'AI-generated scene: adult learners and a trainer working together on a laptop':'KI-generierte Szene: Erwachsene lernen gemeinsam mit einer Trainerin am Laptop';
 document.querySelector('#message').placeholder=locale==='en'?'For example: I want a career change and would like to study part time.':'Zum Beispiel: Ich möchte mich beruflich verändern und in Teilzeit lernen.';
 renderProgrammes();renderFunding();if(!document.querySelector('#form-result').hidden)renderPreview();
 try{localStorage.setItem('weiterwerk-locale',locale);}catch{}
}
document.querySelector('#locale').addEventListener('click',()=>{locale=locale==='en'?'de':'en';applyLocale();const url=new URL(location.href);url.searchParams.set('lang',locale);history.replaceState(null,'',url);});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;renderProgrammes(true);}));
document.querySelectorAll('[data-path]').forEach(link=>link.addEventListener('click',()=>{category=link.dataset.path;mode.value='all';renderProgrammes(true);}));
mode.addEventListener('change',()=>renderProgrammes(true));
document.querySelector('#reset').addEventListener('click',()=>{category='all';mode.value='all';renderProgrammes(true);document.querySelector('[data-filter="all"]').focus();});
document.querySelector('#situation').addEventListener('change',renderFunding);
const menu=document.querySelector('#menu'),navigation=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open);});
navigation.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
document.querySelector('#consultation-form').addEventListener('submit',event=>{event.preventDefault();renderPreview();document.querySelector('#form-result').hidden=false;});
applyLocale();
document.querySelector('#consultation-form button[type="submit"]').disabled=false;
